const root=document.querySelector('#app');
const state={user:null,page:'dashboard',data:null,collapsed:false,mobile:false,unread:0,searchTimer:null,hostelFilter:'',attendanceDate:'',sort:{}};
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const n=x=>Number(x||0).toLocaleString('en-IN');
const esc=e;

function userShape(u){return {...u,name:u.name||u.full_name||'Campus resident',studentId:u.studentId??u.student_id,studentCode:u.studentCode??u.student_code,registrationNumber:u.registrationNumber??u.registration_number,hostel:u.hostel||u.hostel_name,room:u.room||u.room_number,bed:u.bed||u.bed_number};}
function roleLabel(role){return ({admin:'Hostel administrator',warden:'Residence warden',student:'Student resident',security:'Campus security',maintenance:'Maintenance staff',laundry:'Laundry staff'})[role]||role;}

function shellMarkup(){
  const u=state.user;const allowed=new Set(pagesFor(u.role));
  const links=navigation.map(group=>{const visible=group.items.filter(item=>allowed.has(item.id));if(!visible.length)return '';return `<div class="nav-section-label">${esc(group.section)}</div>${visible.map(item=>`<a class="nav-link ${state.page===item.id?'active':''}" href="/app/${item.id}" data-nav="${item.id}" ${state.page===item.id?'aria-current="page"':''} title="${esc(item.label)}">${icon(item.icon)}<span class="nav-label">${esc(item.label)}</span></a>`).join('')}`;}).join('');
  const initialsText=initials(u.name),emergency=allowed.has('safety');
  return `<div class="app-shell"><aside id="sidebar" class="sidebar ${state.collapsed?'collapsed':''} ${state.mobile?'mobile-open':''}" aria-label="Main navigation"><div class="sidebar-top"><a href="/app/dashboard" class="brand" data-nav="dashboard"><span class="brand-mark">${icon('campus')}</span><span class="brand-copy"><span class="brand-name">SmartStay</span><span class="brand-sub">Campus residence portal</span></span></a><button class="icon-action hide" data-action="collapse-sidebar" aria-label="Collapse navigation">${icon('menu')}</button></div><nav class="nav-scroll">${links}</nav><div class="sidebar-bottom"><button class="user-row" data-action="profile" style="width:100%;border:0;background:transparent;text-align:left;color:inherit"><span class="avatar ${u.role==='student'?'blue':u.role==='warden'?'green':''}">${esc(initialsText)}</span><span class="user-copy"><strong>${esc(u.name)}</strong><small>${esc(roleLabel(u.role))}</small></span><span class="profile-chevron">${icon('settings')}</span></button><button class="nav-link" data-action="logout" style="width:100%;border:0;background:transparent"><span class="icon">${icon('logout')}</span><span class="nav-label">Sign out</span></button></div></aside><div class="mobile-scrim ${state.mobile?'visible':''}" data-action="close-mobile"></div><main id="main-area" class="main-area ${state.collapsed?'expanded':''}"><header class="topbar"><div class="top-left"><button class="btn-icon mobile-menu" data-action="toggle-mobile" aria-label="Open navigation">${icon('menu')}</button><button class="btn-icon collapse-desktop" data-action="collapse-sidebar" aria-label="Collapse navigation">${icon('menu')}</button><div><div class="crumb">SmartStay <span>›</span> <b>${esc(routeTitles[state.page]||'Dashboard')}</b></div><div class="page-headline">${esc(routeTitles[state.page]||'Dashboard')}</div></div></div><div class="top-actions"><div class="search-box"><span class="icon">${icon('search')}</span><input id="global-search" type="search" autocomplete="off" placeholder="Search campus" aria-label="Search residents, rooms and service tickets"><div id="global-search-results" class="search-results hide"></div></div>${emergency?`<button class="emergency-shortcut" data-action="emergency"><span class="icon">${icon('emergency')}</span> Emergency help</button>`:''}<span class="header-divider"></span><button class="icon-action" data-nav="notifications" aria-label="Notifications">${icon('bell')}${state.unread?`<span class="unread-dot" aria-label="${state.unread} unread"></span>`:''}</button><button class="icon-action" data-action="profile" aria-label="Your profile"><span class="avatar ${u.role==='student'?'blue':''}" style="width:28px;height:28px">${esc(initialsText)}</span></button></div></header><div class="content" id="page">${state.data===null?`<div class="empty-state"><span class="loading-dot"></span><strong>Opening your residence workspace</strong></div>`:state.page==='dashboard'?renderDashboard(u,state.data):renderPage(state.page,state.data,u)}</div></main></div>`;
}

function valueCounts(list,key='status'){const result={};for(const item of list||[]){const v=item[key]||'Not recorded';result[v]=(result[v]||0)+Number(item.count??1);}return result;}
function dashboardShape(raw,safety,user){
  const residents=Array.isArray(raw.students)?raw.students:[];const attendance=valueCounts(raw.attendance||[],'status');
  const hostelRows=(raw.hostels||[]).map(h=>({...h,hostel_name:h.name,total_beds:Number(h.total_beds||0),occupied_beds:Number(h.occupied_beds||0)}));
  const totalBeds=Number(raw.beds||hostelRows.reduce((a,h)=>a+h.total_beds,0));const occupied=Number(raw.occupied||hostelRows.reduce((a,h)=>a+h.occupied_beds,0));
  const gates=raw.gate||[];const outsideRows=gates.filter(g=>!g.entry_time&&['Outside Hostel','On Leave','Late'].includes(g.status)).map(g=>({...g,hostel_name:g.hostel,student_id:g.student_id}));
  const leaves=raw.leaves||[];const maintenance=raw.maintenanceTasks||[];const laundry=raw.laundryTasks||[];
  const pendingComplaints=Number(raw.pendingComplaints||0);const pendingLeaves=leaves.filter(l=>l.status==='Pending').length;
  const counts={students:Number(raw.students||residents.length),occupied,available:Number(raw.available||Math.max(0,totalBeds-occupied)),onLeave:Number(raw.onLeave||attendance['On Leave']||0),outside:Number(raw.outside||outsideRows.length),complaints:pendingComplaints,maintenance:Number(raw.maintenance||0),visitors:Number(raw.visitors||0),present:Number(raw.present||attendance.Present||0),absent:Number(raw.absent||attendance.Absent||0),pendingLeaves,pendingComplaints};
  const attendanceRows=[{status:'Present',count:counts.present},{status:'Absent',count:counts.absent},{status:'On Leave',count:counts.onLeave},{status:'Outside Hostel',count:counts.outside}];
  const activities=(raw.activity||[]).map(a=>({kind:a.entity==='maintenance_requests'?'maintenance':a.entity==='complaints'?'complaint':'leave',message:`${a.full_name||'Residence team'} · ${a.action}`,created_at:a.created_at}));
  const approvalRows=leaves.filter(l=>l.status==='Pending').map(l=>({code:l.request_code,title:l.leave_type,status:l.status,created_at:l.created_at,full_name:l.full_name,hostel_name:l.hostel}));
  const recentGate=gates.slice(0,8).map(g=>({...g,hostel_name:g.hostel}));
  const allOpenAlerts=(safety?.alerts||[]).filter(a=>!['Resolved','Closed'].includes(a.status)).map(a=>({...a,hostel_name:a.hostel}));
  const student=raw.me?{...raw.me,name:raw.me.full_name,hostel:raw.me.hostel,room:raw.me.room_number,bed:raw.me.bed_number,registrationNumber:raw.me.registration_number,studentCode:raw.me.student_code,attendance:raw.me.attendance_percentage,status:raw.me.current_status}:user;
  if(user.role==='security'){
    const late=gates.filter(g=>g.status==='Late'&&g.entry_time&&String(g.entry_time).slice(0,10)===today()).length;
    return {role:user.role,counts:{...counts,late,approvedLeaves:(raw.allLeaves||[]).filter(l=>['Approved','Active'].includes(l.status)).length,todayMovements:gates.filter(g=>String(g.created_at||'').slice(0,10)===today()).length},outside:outsideRows,recent:gates};
  }
  if(user.role==='maintenance')return {role:user.role,counts:{assigned:maintenance.filter(m=>m.status==='Assigned').length,inProgress:maintenance.filter(m=>m.status==='In Progress').length,reported:maintenance.filter(m=>m.status==='Reported').length,completedToday:maintenance.filter(m=>m.status==='Resolved'&&String(m.updated_at||'').slice(0,10)===today()).length},tasks:maintenance.map(m=>({...m,hostel_name:m.hostel}))};
  if(user.role==='laundry')return {role:user.role,counts:valueCounts(laundry),requests:laundry.map(x=>({...x,student_name:x.full_name,hostel_name:x.hostel}))};
  if(user.role==='student')return {student,leave:(raw.allLeaves||[])[0]||null,gate:gates,maintenance:maintenance.filter(m=>!['Resolved','Verified'].includes(m.status)),laundry,laundry:laundry.map(x=>({...x,student_name:x.full_name,hostel_name:x.hostel})),cleaning:raw.cleaning||[],notifications:(raw.notifications||[]).filter(x=>!x.read_at).length};
  return {role:user.role,counts,hostels:hostelRows,totalBeds,occupied,occupancy:totalBeds?Math.round(occupied*1000/totalBeds)/10:0,attendance:{present:counts.present,absent:counts.absent,onLeave:counts.onLeave,outside:counts.outside},approvals:approvalRows,recentGate,activities,maintenanceBreakdown:valueCounts(maintenance),alerts:allOpenAlerts};
}

async function pageData(page,user){
  if(page==='dashboard'){
    const raw=await get('/dashboard');let safety=null;if(['admin','warden'].includes(user.role))safety=await get('/safety').catch(()=>null);return dashboardShape(raw,safety,user);
  }
  if(page==='reports'){
    const [occupancy,dash,maintenance,complaints,leaves,laundry]=await Promise.all([get('/reports?type=Occupancy'),get('/dashboard'),get('/maintenance'),get('/complaints'),get('/leaves'),get('/laundry')]);
    return {occupancy:(occupancy.rows||[]).map(x=>({name:x.Hostel,beds:x.Beds,occupied:x.Occupied})),attendance:dash.attendance||[],maintenance:Object.entries(valueCounts(maintenance)).map(([status,count])=>({status,count})),complaints:Object.entries(valueCounts(complaints,'category')).map(([category,count])=>({category,count})),leaves:Object.entries(valueCounts(leaves)).map(([status,count])=>({status,count})),laundry:Object.entries(valueCounts(laundry)).map(([status,count])=>({status,count}))};
  }
  if(page==='attendance'){
    const date=state.attendanceDate||today();const raw=await get(`/attendance?from=${encodeURIComponent(date)}&to=${encodeURIComponent(date)}`);const byStudent=new Map((raw.records||[]).map(r=>[r.student_id,r]));return {date,records:raw.records||[],biometrics:raw.biometrics||[],attendance:(raw.students||[]).map(s=>{const a=byStudent.get(s.id);return {...s,student_id:s.id,attendance_status:a?.status||s.attendance_status,source:a?.source,recorded_at:a?.recorded_at};})};
  }
  const raw=await get(`/${page}`);
  if(page==='students')return {students:(raw||[]).map(s=>({...s,hostel_name:s.hostel,room_number:s.room_number,bed_number:s.bed_number}))};
  if(page==='hostels')return {hostels:(raw||[]).map(h=>({...h,warden_name:h.warden,category:h.category||'Campus'}))};
  if(page==='rooms'){
    const list=Array.isArray(raw)?raw:[];return {rooms:list.map(r=>({...r,hostel_name:r.hostel, beds:r.beds||Array.from({length:Number(r.total_beds||r.capacity||0)},(_,i)=>({id:`${r.id}-${i+1}`,room_id:r.id,bed_number:i+1,status:i<Number(r.occupied_beds||0)?'Occupied':'Available'}))}))};
  }
  if(page==='allocations'){
    const rows=raw.allocations||[];const active=rows.filter(x=>!x.vacated_at);return {allocations:active.map(a=>({...a,hostel_name:a.hostel,bed_id:a.bed_id})),history:rows,availableBeds:(raw.availableBeds||[]).map(b=>({...b,hostel_name:b.hostel,bed_number:b.bed_number}))};
  }
  if(page==='wardens')return {wardens:(raw||[]).map(w=>({...w,name:w.full_name,hostel_name:w.hostel}))};
  if(page==='staff')return {staff:(raw||[]).map(s=>({...s,hostel_name:s.hostel,active_tasks:s.tasks_assigned}))};
  if(page==='gate'){
    const logs=(raw.logs||[]).map(x=>({...x,hostel_name:x.hostel}));const people=(raw.students||[]).map(s=>({...s,full_name:s.full_name,student_code:s.student_code,hostel_name:s.hostel,phone:s.phone}));return {...raw,logs,students:people,keys:(raw.keys||[]).map(k=>({...k,hostel_name:k.hostel,full_name:k.full_name})) ,outside:logs.filter(g=>!g.entry_time&&['Outside Hostel','On Leave','Late'].includes(g.status))};
  }
  if(page==='leaves')return {leaves:(raw||[]).map(x=>({...x,hostel_name:x.hostel}))};
  if(page==='maintenance'){const staff=['admin','warden'].includes(user.role)?await get('/staff'):[];return {requests:(raw||[]).map(x=>({...x,student_name:x.full_name,hostel_name:x.hostel,assigned_staff_name:x.staff_name})),staff:staff.filter(s=>['Maintenance','Electrician','Plumber'].includes(s.role))};}
  if(page==='complaints')return {complaints:(raw||[]).map(x=>({...x,reporter_name:x.full_name,hostel_name:x.hostel}))};
  if(page==='laundry')return {requests:(raw||[]).map(x=>({...x,student_name:x.full_name,hostel_name:x.hostel}))};
  if(page==='notifications')return {notifications:raw||[],unread:(raw||[]).filter(x=>!x.read_at).length};
  if(page==='safety')return {...raw,alerts:(raw.alerts||[]).map(x=>({...x,hostel_name:x.hostel}))};
  if(page==='iot')return {demo:true,devices:(raw||[]).map(x=>({...x,hostel_name:x.hostel}))};
  if(page==='cleaning')return {tasks:(raw||[]).map(x=>({...x,hostel_name:x.hostel}))};
  if(page==='inspections')return {inspections:(raw||[]).map(x=>({...x,hostel_name:x.hostel,inspector:x.full_name}))};
  if(page==='feedback')return {feedback:(raw||[]).map(x=>({...x,average:x.rating})),comments:[]};
  if(page==='settings')return {settings:raw.values||{},profile:raw.profile,audit:raw.audit||[],recovery:raw.recovery||[]};
  return raw;
}

function showShell(){document.title=`${routeTitles[state.page]||'Dashboard'} · SmartStay`;document.body.className='app-body';root.innerHTML=shellMarkup();applyTables(root);}
async function navigate(page,{replace=false}={}){
  const allowed=pagesFor(state.user.role);if(!allowed.includes(page)){page='dashboard';toast('This workspace does not have access to that module.','warning');}
  state.page=page;state.data=null;state.mobile=false;if(replace)history.replaceState({},'',`/app/${page}`);else if(location.pathname!==`/app/${page}`)history.pushState({},'',`/app/${page}`);showShell();
  try{state.data=await pageData(page,state.user);if(page==='notifications')state.unread=state.data.unread||0;showShell();}
  catch(err){if(err.status===401){location.href='/login';return;}state.data={error:err.message};showError(err.message);}
}
function showError(message){const main=document.querySelector('#page');if(main)main.innerHTML=`<div class="panel"><div class="empty-state"><strong>We couldn't load this view.</strong>${esc(message)}<div style="margin-top:14px"><button class="btn btn-primary" data-action="retry-page">Try again</button></div></div></div>`;}
async function initialize(){
  const path=location.pathname;
  if(path==='/'||path==='/index.html'||path==='/login')return;
  try{const me=await get('/me');state.user=userShape(me.user);const unread=await get('/notifications').catch(()=>[]);state.unread=Array.isArray(unread)?unread.filter(x=>!x.read_at).length:0;const requested=path.startsWith('/app/')?path.slice(5).split('/')[0]:'dashboard';await navigate(requested,{replace:true});}
  catch(err){if(err.status===401){location.href='/login';return;}root.innerHTML=`<div class="empty-state"><strong>SmartStay couldn't open.</strong>${esc(err.message)}</div>`;}
}

function openForm(title,key,fields,values={},subtitle='',submit='Save changes',{wide=true}={}){
  const body=`<form id="modal-form" data-form="${esc(key)}"><div class="form-grid">${fields.join('')}</div></form>`;
  const actions=`<button class="btn btn-outline" type="button" data-action="close-modal">Cancel</button><button class="btn btn-primary" type="submit" form="modal-form">${esc(submit)}</button>`;
  return modal({title,subtitle,body,actions,wide});
}
function f(name,label,type='text',opts={}){
  const req=opts.required===false?'':'required';const val=opts.value??'';const full=opts.full?'full':'';
  if(type==='select')return `<div class="form-field ${full}"><label for="f-${name}">${esc(label)}${req?' *':''}</label><select id="f-${name}" name="${name}" ${req}>${(opts.options||[]).map(([v,l])=>`<option value="${esc(v)}" ${String(v)===String(val)?'selected':''}>${esc(l)}</option>`).join('')}</select></div>`;
  if(type==='textarea')return `<div class="form-field ${full}"><label for="f-${name}">${esc(label)}${req?' *':''}</label><textarea id="f-${name}" name="${name}" ${req} maxlength="2000" placeholder="${esc(opts.placeholder||'')}">${esc(val)}</textarea></div>`;
  if(type==='checkbox')return `<div class="form-field ${full}"><label class="checkbox-line"><input id="f-${name}" name="${name}" type="checkbox" ${val?'checked':''} ${opts.required===true?'required':''}> ${esc(label)}</label>${opts.hint?`<small class="muted">${esc(opts.hint)}</small>`:''}</div>`;
  return `<div class="form-field ${full}"><label for="f-${name}">${esc(label)}${req?' *':''}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(val)}" ${req} ${opts.min!==undefined?`min="${opts.min}"`:''} ${opts.max!==undefined?`max="${opts.max}"`:''} ${opts.placeholder?`placeholder="${esc(opts.placeholder)}"`:''}></div>`;
}
function val(form){const data=Object.fromEntries(new FormData(form).entries());form.querySelectorAll('input[type=checkbox]').forEach(c=>data[c.name]=c.checked);return data;}
function dateNow(){return today();}

async function studentDialog(id){
  if(id){const s=await get(`/students/${id}`);const details=[['Student ID',s.student_code],['Registration',s.registration_number],['Department',s.department],['Year',`Year ${s.year}`],['Phone',s.phone],['Email',s.email],['Residence',s.hostel],['Room',s.room_number],['Bed',s.bed_number],['Guardian',s.guardian_name],['Guardian contact',s.guardian_phone],['Emergency contact',s.emergency_phone],['Attendance',`${s.attendance_percentage||0}%`],['Current status',s.current_status]];modal({title:s.full_name,subtitle:'Student residence profile',wide:true,body:`<div class="detail-grid">${details.map(([a,b])=>`<div class="detail-item"><span>${esc(a)}</span><strong>${esc(b||'—')}</strong></div>`).join('')}</div><div class="dash-grid equal" style="margin-top:14px"><section class="panel"><div class="panel-head"><h2 class="section-title">Recent attendance</h2></div><div class="panel-body">${(s.attendance||[]).slice(0,6).map(a=>`<div class="staff-task"><span>${dateLabel(a.attendance_date)}</span>${badge(a.status)}</div>`).join('')||'<div class="empty-note">No attendance history.</div>'}</div></section><section class="panel"><div class="panel-head"><h2 class="section-title">Residence history</h2></div><div class="panel-body">${(s.leaves||[]).slice(0,5).map(a=>`<div class="staff-task"><span>${esc(a.request_code)} · ${dateLabel(a.from_date)}</span>${badge(a.status)}</div>`).join('')||'<div class="empty-note">No leave records.</div>'}</div></section></div>`});return;}
  const hostels=await get('/hostels');const isEdit=false;const fields=[f('full_name','Student name'),f('email','College email','email'),f('password','Initial password','password',{required:false,placeholder:'Defaults to Student@123'}),f('phone','Student phone','tel'),f('registration_number','Registration number'),f('department','Department','select',{options:['CSE','CSE-AI','CSE-DS','ECE','EEE','Mechanical','Civil'].map(x=>[x,x])}),f('year','Year','number',{min:1,max:6}),f('hostel_id','Residence hostel','select',{options:hostels.map(h=>[h.id,h.name])}),f('guardian_name','Parent / guardian'),f('guardian_phone','Guardian phone','tel'),f('emergency_phone','Emergency contact','tel')];
  openForm('Add a student','student-create',fields,{},'Create a campus resident profile and add it to the student directory.','Add student',{wide:true});
}
async function editStudent(id){const s=await get(`/students/${id}`);const fields=[f('full_name','Student name','text',{value:s.full_name}),f('email','College email','email',{value:s.email}),f('phone','Student phone','tel',{value:s.phone}),f('department','Department','select',{value:s.department,options:['CSE','CSE-AI','CSE-DS','ECE','EEE','Mechanical','Civil'].map(x=>[x,x])}),f('year','Year','number',{value:s.year,min:1,max:6}),f('guardian_name','Parent / guardian','text',{value:s.guardian_name}),f('guardian_phone','Guardian phone','tel',{value:s.guardian_phone}),f('emergency_phone','Emergency contact','tel',{value:s.emergency_phone})];openForm('Edit student details','student-edit',fields,{id},'Update the resident profile and emergency contact information.','Save changes');document.querySelector('#modal-form').dataset.id=id;}
async function allocationDialog(studentId=null,transfer=false){const [students,raw]=await Promise.all([get('/students'),get('/allocations')]);const beds=raw.availableBeds||[];if(!beds.length){toast('There are no available beds to allocate.','warning');return;}const options=students.filter(s=>s.active).map(s=>[s.id,`${s.full_name} · ${s.registration_number}`]);const bedOptions=beds.map(b=>[b.bed_id||b.id,`${b.hostel||b.hostel_name} · ${b.room_number} · Bed ${b.bed_number}`]);openForm(transfer?'Transfer room assignment':'Allocate a room','allocation-save',[f('student_id','Student','select',{value:studentId||'',options}),f('bed_id','Available bed','select',{options:bedOptions}),f('note','Allocation note','text',{required:false}),f('transfer','Transfer existing assignment','checkbox',{value:transfer,hint:'The previous bed is released when you save the transfer.'})],{},'Only available beds are listed. A student can hold one active allocation.','Save allocation');}
async function staffDialog(warden=false){const [hostels]=await Promise.all([get('/hostels')]);const fields=[f('full_name',warden?'Warden name':'Staff name'),f('email','Account email','email'),f('password','Initial password','password',{required:false,placeholder:'At least 8 characters'}),f('phone','Phone','tel'),...(warden?[]:[f('role','Staff role','select',{options:['Cleaning','Maintenance','Electrician','Plumber','Security','Laundry'].map(x=>[x,x])})]),f('hostel_id','Assigned hostel','select',{options:hostels.map(h=>[h.id,h.name])}),f('shift','Shift','select',{options:['Day','Evening','Night'].map(x=>[x,x])})];openForm(warden?'Add warden':'Add hostel staff member',warden?'warden-create':'staff-create',fields,{},'Campus team member and account access.','Save team member');}

function attendanceDialog(id,name){const fields=[f('status','Attendance status','select',{value:'Present',options:['Present','Absent','On Leave','Outside Hostel','Medical Leave'].map(x=>[x,x])}),f('attendance_date','Date','date',{value:today()}),f('source','Source','select',{value:'Manual',options:[['Manual','Manual register']]})];openForm(`Record attendance · ${name}`,'attendance-save',fields,{},'Attendance is saved to the resident’s daily record.','Record status');document.querySelector('#modal-form').dataset.studentId=id;}
