function leaveDialog(){const fields=[f('leave_type','Leave type','select',{options:['Normal Leave','Emergency Leave','Medical Leave'].map(x=>[x,x])}),f('from_date','Leaving date','date',{value:today()}),f('to_date','Return date','date',{value:today()}),f('departure_time','Departure time','time',{value:'18:00'}),f('expected_return','Expected return time','time',{value:'21:00'}),f('destination','Destination','text'),f('emergency_contact','Emergency contact','tel',{value:state.user.phone||''}),f('reason','Reason','textarea',{full:true})];openForm('Apply for residence leave','leave-create',fields,{},'Your warden reviews the request and shares approved leave with campus security.','Submit leave request');}
