function emergencyDialog(){const fields=[f('emergency_type','Emergency type','select',{options:['Medical Emergency','Fire','Security Issue','Harassment/Safety Concern','Other'].map(x=>[x,x])}),f('contact_number','Contact number','tel',{value:state.user.emergencyPhone||state.user.phone||''}),f('details','What help do you need?','textarea',{full:true}),f('confirmed','Confirm emergency request','checkbox',{hint:'I confirm that this request needs immediate campus response.'})];openForm('Request emergency help','emergency-create',fields,{},'This will alert your warden, campus security and hostel administration.','Send emergency alert');}
