function profileDialog(){const u=state.user;const body=`<div class="detail-grid"><div class="detail-item"><span>Name</span><strong>${esc(u.name)}</strong></div><div class="detail-item"><span>Role</span><strong>${esc(roleLabel(u.role))}</strong></div><div class="detail-item"><span>Campus email</span><strong>${esc(u.email)}</strong></div><div class="detail-item"><span>Phone</span><strong>${esc(u.phone||'—')}</strong></div>${u.role==='student'?`<div class="detail-item"><span>Registration</span><strong>${esc(u.registrationNumber||'—')}</strong></div><div class="detail-item"><span>Residence</span><strong>${esc(u.hostel||'—')} · ${esc(u.room||'—')}</strong></div>`:''}</div><div style="border-top:1px solid #edf0f5;margin-top:18px;padding-top:15px"><button class="btn btn-outline btn-sm" data-action="password-change">${icon('key')} Change password</button></div>`;modal({title:'Your SmartStay account',subtitle:'Campus residence profile',body});}

async function dispatchForm(form){const data=val(form),kind=form.dataset.form,id=form.dataset.id;const submit=form.querySelector('[type=submit]');if(submit){submit.disabled=true;submit.innerHTML='<span class="loading-dot"></span> Saving';}
  try{
    if(kind==='student-create')await post('/students',data);
    else if(kind==='student-edit')await patch(`/students/${id}`,data);
    else if(kind==='allocation-save')await post('/allocations',data);
    else if(kind==='staff-create'||kind==='warden-create'){if(kind==='warden-create')data.role='Warden';await post(kind==='warden-create'?'/wardens':'/staff',data);}
    else if(kind==='attendance-save'){const studentId=form.dataset.studentId;await post('/attendance',{...data,student_id:Number(studentId)});if(data.source&&data.source!=='Manual')toast(`Demo biometric event verified by ${data.source}.`);}
    else if(kind==='gate-record'){const expected=data.expected_return?new Date(data.expected_return).toISOString():undefined;await post('/gate',{student_id:Number(data.student_id),action:data.action,reason:data.reason||'Campus visit',expected_return:expected});}
    else if(kind==='leave-create')await post('/leaves',data);
    else if(kind==='maintenance-create')await post('/maintenance',data);
    else if(kind==='maintenance-update'){const body={status:data.status};if(data.assigned_staff_id)body.assigned_staff_id=Number(data.assigned_staff_id);if(data.resolution)body.resolution=data.resolution;await patch(`/maintenance/${id}`,body);}
    else if(kind==='complaint-create')await post('/complaints',data);
    else if(kind==='complaint-update')await patch(`/complaints/${id}`,data);
    else if(kind==='laundry-create')await post('/laundry',data);
    else if(kind==='laundry-update')await patch(`/laundry/${id}`,data);
    else if(kind==='emergency-create')await post('/safety',{...data,confirmed:data.confirmed===true});
    else if(kind==='emergency-update')await patch(`/safety/${id}`,data);
    else if(kind==='inspection-create')await post('/inspections',data);
    else if(kind==='cleaning-create')await post('/cleaning',data);
    else if(kind==='feedback-create')await post('/feedback',data);
    else if(kind==='settings')await patch('/settings',data);
    else if(kind==='password-change'){
      if(data.new_password!==data.confirm_password)throw new Error('The new passwords do not match.');await post('/auth/password',{current_password:data.current_password,new_password:data.new_password});location.href='/login';return;
    }
    document.querySelector('.modal-backdrop')?.remove();toast(kind==='emergency-create'?'Emergency alert sent to campus response staff.':'Saved successfully.');await navigate(state.page,{replace:true});
  }catch(err){if(submit){submit.disabled=false;submit.textContent='Try again';}toast(err.message||'Unable to save. Please try again.','error');}
}

function studentEditRole(st){const allowed=pagesFor(state.user.role).includes('students');return allowed;}
async function action(target){const a=target.dataset.action,id=target.dataset.id;
  if(a==='collapse-sidebar'){state.collapsed=!state.collapsed;document.querySelector('#sidebar')?.classList.toggle('collapsed',state.collapsed);document.querySelector('#main-area')?.classList.toggle('expanded',state.collapsed);return;}
  if(a==='toggle-mobile'){state.mobile=true;document.querySelector('#sidebar')?.classList.add('mobile-open');document.querySelector('.mobile-scrim')?.classList.add('visible');return;}
  if(a==='close-mobile'){state.mobile=false;document.querySelector('#sidebar')?.classList.remove('mobile-open');document.querySelector('.mobile-scrim')?.classList.remove('visible');return;}
  if(a==='close-modal'){document.querySelector('.modal-backdrop')?.remove();return;}
  if(a==='logout'){try{await post('/auth/logout',{});}catch{}location.href='/';return;}
  if(a==='profile'){profileDialog();return;}
  if(a==='password-change'){const fields=[f('current_password','Current password','password'),f('new_password','New password','password',{min:8}),f('confirm_password','Confirm new password','password',{min:8})];openForm('Change your password','password-change',fields,{},'Use at least 8 characters. You will need to sign in again.','Update password');return;}
  if(a==='retry-page'){await navigate(state.page,{replace:true});return;}
  if(a==='student-add'){await studentDialog();return;}
  if(a==='student-view'){await studentDialog(id);return;}
  if(a==='student-edit'){await editStudent(id);return;}
  if(a==='student-deactivate'){confirmDialog({title:'Deactivate student?',message:`${target.dataset.name} will lose account access. The current bed allocation will be released.`,confirm:'Deactivate',danger:true,onConfirm:async()=>{try{await patch(`/students/${id}`,{action:'deactivate'});toast('Student deactivated and bed released.');await navigate(state.page,{replace:true});}catch(err){toast(err.message,'error');}}});return;}
  if(a==='allocation-add'){await allocationDialog();return;}
  if(a==='allocation-transfer'){await allocationDialog(id,true);return;}
  if(a==='allocation-vacate'){confirmDialog({title:'Vacate this student bed?',message:`This will release the allocated bed for ${target.dataset.name} and clear the current room assignment.`,confirm:'Vacate bed',danger:true,onConfirm:async()=>{try{await post('/allocations',{action:'vacate',student_id:Number(id)});toast('Bed vacated and available for allocation.');await navigate(state.page,{replace:true});}catch(err){toast(err.message,'error');}}});return;}
  if(a==='staff-add'){await staffDialog(false);return;}
  if(a==='warden-add'){await staffDialog(true);return;}
  if(a==='attendance-mark'){attendanceDialog(id,target.dataset.name);return;}
  if(a==='biometric-demo'){const list=state.data?.attendance||[];const fields=[f('student_id','Student ID','select',{options:list.slice(0,100).map(s=>[s.student_id,`${s.full_name} · ${s.registration_number}`])}),f('method','Biometric method','select',{options:['RFID','Fingerprint','Face recognition','Smart ID card'].map(x=>[x,x])})];openForm('Simulate biometric attendance','biometric-save',fields,{},'Demonstration only; this does not connect to a fingerprint or face reader.','Record demo event');return;}
  if(a==='gate-record'){gateDialog();return;}
  if(a==='room-details'){const room=(state.data?.rooms||[]).find(r=>String(r.id)===String(id));if(!room)return;const body=`<div class="detail-grid"><div class="detail-item"><span>Residence</span><strong>${esc(room.hostel_name)}</strong></div><div class="detail-item"><span>Floor</span><strong>${room.floor_number}</strong></div><div class="detail-item"><span>Room type</span><strong>${esc(room.room_type)}</strong></div><div class="detail-item"><span>Cleaning</span><strong>${esc(room.cleaning_status||'Clean')}</strong></div><div class="detail-item"><span>Maintenance</span><strong>${esc(room.maintenance_status||'Clear')}</strong></div><div class="detail-item"><span>Lights / door</span><strong>${esc(room.lights_status||'—')} · ${esc(room.door_status||'—')}</strong></div></div><div style="margin-top:16px"><div class="eyebrow" style="margin-bottom:9px">Bed assignments</div><div class="bed-grid">${(room.beds||[]).map(b=>`<span class="bed-chip ${b.status==='Occupied'?'occupied':''}"><strong>Bed ${b.bed_number}</strong>${b.status==='Occupied'?esc(b.full_name?.split(' ')[0]||'Occupied'):'Available'}</span>`).join('')}</div></div>`;modal({title:`Room ${room.room_number}`,subtitle:`${room.occupied_beds||0} of ${room.total_beds||room.capacity} beds occupied`,body});return;}
  if(a==='gate-search'){
    const term=document.querySelector('#gate-search-input')?.value.trim();if(!term){toast('Enter a student ID, registration or name.','warning');return;}const {students=[]}=state.page==='dashboard'?await get('/gate'):state.data;const found=students.find(s=>[s.student_code,s.registration_number,String(s.id),s.full_name].some(v=>String(v||'').toLowerCase()===term.toLowerCase()))||students.find(s=>[s.student_code,s.registration_number,s.full_name].some(v=>String(v||'').toLowerCase().includes(term.toLowerCase())));const box=document.querySelector('#gate-search-result');if(!found){box.innerHTML=`<div class="empty-note">No resident matched “${esc(term)}”. Check the ID or registration number.</div>`;return;}const status=found.current_status||'Inside Hostel';box.innerHTML=`<div class="scan-result"><div class="scan-result-info"><span class="avatar blue">${esc(initials(found.full_name))}</span><span><strong>${esc(found.full_name)} · ${esc(found.student_code)}</strong><small>${esc(found.registration_number)} · ${esc(found.hostel||found.hostel_name||'Hostel')} · ${esc(found.room_number||'—')} · Bed ${esc(found.bed_number||'—')}</small>${badge(status)}</span></div><div class="scan-buttons"><button class="btn btn-primary" data-action="gate-entry" data-student="${found.id}" ${status==='Inside Hostel'?'disabled':''}>${icon('gate')} Record entry</button><button class="btn btn-outline" data-action="gate-exit" data-student="${found.id}" data-name="${esc(found.full_name)}" ${status==='Outside Hostel'||status==='On Leave'?'disabled':''}>Record exit</button></div></div>`;return;
  }
  if(a==='gate-entry'||a==='gate-quick-entry'){try{await post('/gate',{student_id:Number(target.dataset.student),action:'entry'});toast('Student entry recorded.');await navigate(state.page,{replace:true});}catch(err){toast(err.message,'error');}return;}
  if(a==='gate-exit'){gateDialog(target.dataset.student,target.dataset.name);return;}
  if(a==='key-handover'){const students=state.data?.students||[];const fields=[f('student_id','Student','select',{options:students.map(s=>[s.id,`${s.full_name} · ${s.registration_number}`])}),f('key_code','Room key ID')];openForm('Record room key handover','key-submit',fields,{},'Record who is holding the room key while a student is away.','Record handover');return;}
  if(a==='key-return'){try{await post('/keys',{student_id:Number(id),action:'return'});toast('Key returned and acknowledged.');await navigate(state.page,{replace:true});}catch(err){toast(err.message,'error');}return;}
  if(a==='leave-new'){leaveDialog();return;}
  if(a==='leave-review'){const fields=[f('status','Decision','select',{options:[['Approved','Approve leave'],['Rejected','Reject request']]}),f('review_note','Note for student','textarea',{full:true,required:false})];openForm(`Review ${target.dataset.name}’s leave`,'leave-review',fields,{},'An approval is visible to security at the residence gate.','Save decision');document.querySelector('#modal-form').dataset.id=id;return;}
  if(a==='maintenance-new'){maintenanceCreate();return;}
  if(a==='maintenance-edit'){await maintenanceEdit(id,target.dataset.ticket,target.dataset.status,target.dataset.priority);return;}
  if(a==='maintenance-update'){
    const status=target.dataset.status,body={status};if(status==='Resolved')body.resolution='Completed by the residence maintenance team.';try{await patch(`/maintenance/${id}`,body);toast(`Maintenance marked ${status.toLowerCase()}.`);await navigate(state.page,{replace:true});}catch(err){toast(err.message,'error');}return;
  }
  if(a==='maintenance-verify'){confirmDialog({title:'Verify the repair?',message:'Confirm that the maintenance issue is resolved in your room.',confirm:'Verify repair',onConfirm:async()=>{try{await patch(`/maintenance/${id}`,{status:'Verified'});toast('Repair marked verified.');await navigate('maintenance',{replace:true});}catch(err){toast(err.message,'error');}}});return;}
  if(a==='complaint-new'){complaintDialog();return;}
  if(a==='complaint-update'){complaintUpdate(id,target.dataset.code,target.dataset.status);return;}
  if(a==='laundry-new'){laundryCreate();return;}
  if(a==='laundry-edit'){const fields=[f('status','Update laundry status','select',{value:target.dataset.status,options:['Requested','Collected','Washing','Ready','Delivered'].map(x=>[x,x])})];openForm(`Update ${target.dataset.code}`,'laundry-update',fields,{},'Laundry statuses move forward through collection and return.','Save status');document.querySelector('#modal-form').dataset.id=id;return;}
  if(a==='laundry-update'){try{await patch(`/laundry/${id}`,{status:target.dataset.status});toast(`Laundry marked ${target.dataset.status.toLowerCase()}.`);await navigate(state.page,{replace:true});}catch(err){toast(err.message,'error');}return;}
  if(a==='notification-read'){try{await patch(`/notifications/${id}`,{});toast('Notification marked as read.');await navigate(state.page,{replace:true});}catch(err){toast(err.message,'error');}return;}
  if(a==='notification-read-all'){try{await post('/notifications',{});toast('All notifications marked as read.');await navigate(state.page,{replace:true});}catch(err){toast(err.message,'error');}return;}
  if(a==='emergency'){if(state.user.role==='student')emergencyDialog();else navigate('safety');return;}
  if(a==='emergency-new'){emergencyDialog();return;}
  if(a==='emergency-update'){emergencyUpdate(id,target.dataset.status);return;}
  if(a==='inspection-add'){await inspectionDialog();return;}
  if(a==='cleaning-add'){await cleaningDialog();return;}
  if(a==='cleaning-status'){try{await patch(`/cleaning/${id}`,{status:target.dataset.status});toast(`Cleaning task marked ${target.dataset.status.toLowerCase()}.`);await navigate(state.page,{replace:true});}catch(err){toast(err.message,'error');}return;}
  if(a==='feedback-new'){feedbackDialog();return;}
  if(a==='iot-edit'){confirmDialog({title:'Refresh demo sensor values?',message:'SmartStay will generate a fresh set of simulated readings for the campus. No physical IoT device will be contacted.',confirm:'Refresh demo data',onConfirm:async()=>{try{const r=await post('/iot',{});toast(`${r.updated} demo device readings refreshed.`);await navigate('iot',{replace:true});}catch(err){toast(err.message,'error');}}});return;}
  if(a==='export-csv'){exportTable();return;}
}

function exportTable(){const table=document.querySelector('#page table');if(!table){toast('There is no table to export on this page.','warning');return;}const rows=[...table.querySelectorAll('tr')].map(tr=>[...tr.children].map(td=>`"${td.innerText.replaceAll('"','""').replace(/\s+/g,' ').trim()}"`).join(','));const blob=new Blob([rows.join('\r\n')],{type:'text/csv;charset=utf-8'});const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=`smartstay-${state.page}-${today()}.csv`;link.click();URL.revokeObjectURL(link.href);toast('Current table exported as CSV.');}

function applyTables(scope=document){scope.querySelectorAll('.table-wrap').forEach(wrap=>{
  const rows=[...wrap.querySelectorAll('tbody tr[data-row]')];const input=wrap.closest('.panel')?.querySelector('.table-search');const search=input?.value?.toLowerCase().trim()||'';let matches=rows.filter(r=>(r.dataset.search||r.innerText).toLowerCase().includes(search));const pageSize=14;const page=Math.max(1,Number(wrap.dataset.page||1));const pages=Math.max(1,Math.ceil(matches.length/pageSize));const current=Math.min(page,pages);wrap.dataset.page=String(current);rows.forEach(r=>r.hidden=true);matches.slice((current-1)*pageSize,current*pageSize).forEach(r=>r.hidden=false);const info=wrap.parentElement.querySelector('.page-count');if(info)info.textContent=`${matches.length?((current-1)*pageSize+1):0}–${Math.min(current*pageSize,matches.length)} of ${matches.length} records`;const indicator=wrap.parentElement.querySelector('.page-indicator');if(indicator)indicator.textContent=`${current} / ${pages}`;
});}

document.addEventListener('click',async ev=>{
  const nav=ev.target.closest('[data-nav]');if(nav){const page=nav.dataset.nav;if(page){ev.preventDefault();document.querySelector('#global-search-results')?.classList.add('hide');await navigate(page);return;}}
  const anchor=ev.target.closest('a[href^="#/"]');if(anchor){ev.preventDefault();const page=anchor.getAttribute('href').slice(2).split('?')[0];if(anchor.dataset.hostelFilter)state.hostelFilter=anchor.dataset.hostelFilter;await navigate(page);if(state.hostelFilter){const filter=document.querySelector('.room-hostel-filter');if(filter){filter.value=state.hostelFilter;filter.dispatchEvent(new Event('change',{bubbles:true}));}state.hostelFilter='';}return;}
  const step=ev.target.closest('[data-page-step]');if(step){const wrap=step.closest('.panel')?.querySelector('.table-wrap');if(wrap){wrap.dataset.page=String(Math.max(1,Number(wrap.dataset.page||1)+Number(step.dataset.pageStep)));applyTables(wrap.closest('.panel'));}return;}
  const act=ev.target.closest('[data-action]');if(act){await action(act);return;}
  if(!ev.target.closest('.search-box'))document.querySelector('#global-search-results')?.classList.add('hide');
  const th=ev.target.closest('.data-table th');if(th){const wrap=th.closest('.table-wrap');const rows=[...wrap.querySelectorAll('tbody tr[data-row]')];const i=[...th.parentElement.children].indexOf(th);const dir=th.dataset.direction==='asc'?'desc':'asc';th.dataset.direction=dir;rows.sort((a,b)=>{const x=a.children[i]?.innerText.trim()||'',y=b.children[i]?.innerText.trim()||'';return x.localeCompare(y,undefined,{numeric:true})*(dir==='asc'?1:-1);}).forEach(r=>r.parentElement.append(r));wrap.dataset.page='1';applyTables(wrap.closest('.panel'));}
});
document.addEventListener('submit',async ev=>{const form=ev.target;if(form.id==='login-form')return;if(form.id==='modal-form'){ev.preventDefault();if(!form.reportValidity())return;const kind=form.dataset.form;
  if(kind==='biometric-save'){const d=val(form);try{await post('/attendance',{student_id:Number(d.student_id),status:'Present',source:`Demo ${d.method}`,biometric:true,method:d.method,attendance_date:today()});document.querySelector('.modal-backdrop')?.remove();toast(`Biometric event verified by ${d.method}.`);await navigate('attendance',{replace:true});}catch(err){toast(err.message,'error');}return;}
  if(kind==='key-submit'){const d=val(form);try{await post('/keys',{...d,student_id:Number(d.student_id),action:'submit'});document.querySelector('.modal-backdrop')?.remove();toast('Key handover recorded.');await navigate('gate',{replace:true});}catch(err){toast(err.message,'error');}return;}
  if(kind==='gate-record'){const data=val(form);try{const expected=data.expected_return?new Date(data.expected_return).toISOString():undefined;await post('/gate',{student_id:Number(data.student_id),action:data.action,reason:data.reason||'Campus visit',expected_return:expected});document.querySelector('.modal-backdrop')?.remove();toast(`${data.action==='entry'?'Entry':'Exit'} recorded at the residence gate.`);await navigate(state.page,{replace:true});}catch(err){toast(err.message,'error');}return;}
  if(kind==='leave-review'){const data=val(form);try{await patch(`/leaves/${form.dataset.id}`,data);document.querySelector('.modal-backdrop')?.remove();toast(`Leave request ${data.status.toLowerCase()}.`);await navigate(state.page,{replace:true});}catch(err){toast(err.message,'error');}return;}
  if(kind==='laundry-update'){const data=val(form);try{await patch(`/laundry/${form.dataset.id}`,data);document.querySelector('.modal-backdrop')?.remove();toast(`Laundry marked ${data.status.toLowerCase()}.`);await navigate(state.page,{replace:true});}catch(err){toast(err.message,'error');}return;}
  if(kind==='emergency-create'){const data=val(form);if(!data.confirmed){toast('Confirm that you need immediate help before submitting.','warning');return;}try{await post('/safety',{...data,confirmed:true});document.querySelector('.modal-backdrop')?.remove();toast('Emergency alert sent to your residence response team.');await navigate('safety',{replace:true});}catch(err){toast(err.message,'error');}return;}
  await dispatchForm(form);return;}
});
document.addEventListener('input',ev=>{
  if(ev.target.matches('.table-search')){const panel=ev.target.closest('.panel');const wrap=panel?.querySelector('.table-wrap');if(wrap)wrap.dataset.page='1';applyTables(panel);}
  if(ev.target.id==='global-search'){clearTimeout(state.searchTimer);const q=ev.target.value.trim();const box=document.querySelector('#global-search-results');if(q.length<2){box?.classList.add('hide');return;}state.searchTimer=setTimeout(async()=>{try{const result=await get(`/search?q=${encodeURIComponent(q)}`);if(!box)return;box.innerHTML=(result||[]).map(r=>`<a href="/app/${esc(r.module)}" class="search-result" data-nav="${esc(r.module)}"><strong>${esc(r.title)}</strong><small>${esc(r.subtitle)}</small></a>`).join('')||'<div class="empty-note">No matching campus records.</div>';box.classList.remove('hide');}catch{}},180);}
  if(ev.target.matches('.room-search')){const q=ev.target.value.toLowerCase();document.querySelectorAll('.room-card').forEach(card=>card.hidden=!card.innerText.toLowerCase().includes(q));}
});
document.addEventListener('change',ev=>{
  if(ev.target.matches('.room-hostel-filter,.room-status-filter')){const hostel=document.querySelector('.room-hostel-filter')?.value,status=document.querySelector('.room-status-filter')?.value;document.querySelectorAll('.room-card').forEach(card=>{const hostMatch=!hostel||card.querySelector('[data-hostel]')?.dataset.hostel===hostel||card.innerText.includes(document.querySelector('.room-hostel-filter option:checked')?.textContent||'');const statusMatch=!status||card.innerText.toLowerCase().includes(status.toLowerCase());card.hidden=!(hostMatch&&statusMatch);});}
  if(ev.target.id==='attendance-date'){state.attendanceDate=ev.target.value;navigate('attendance',{replace:true});}
});
window.addEventListener('popstate',()=>{if(!state.user)return;const page=location.pathname.startsWith('/app/')?location.pathname.slice(5).split('/')[0]:'dashboard';navigate(page,{replace:true});});
window.addEventListener('keydown',ev=>{if(ev.key==='Escape'){state.mobile=false;document.querySelector('#sidebar')?.classList.remove('mobile-open');document.querySelector('.mobile-scrim')?.classList.remove('visible');}});

initialize();
